Not run; written for Express 5, Node 18+. `npm i express express-session express-rate-limit`. Hashing uses stdlib `crypto.scrypt`, so no bcrypt dependency.

```js
// app.js
const express = require('express');
const session = require('express-session');
const { rateLimit } = require('express-rate-limit');
const { scrypt, randomBytes, timingSafeEqual } = require('node:crypto');
const { promisify } = require('node:util');

const scryptAsync = promisify(scrypt);
const prod = process.env.NODE_ENV === 'production';

if (!process.env.SESSION_SECRET) throw new Error('SESSION_SECRET not set');

// --- password hashing: scrypt, per-user random salt, stored as "salt:key" hex ---
async function hashPassword(password) {
  const salt = randomBytes(16);
  const key = await scryptAsync(password, salt, 64);
  return `${salt.toString('hex')}:${key.toString('hex')}`;
}

async function verifyPassword(password, stored) {
  const [salt, key] = stored.split(':').map((h) => Buffer.from(h, 'hex'));
  return timingSafeEqual(key, await scryptAsync(password, salt, 64));
}

// Verified against when the user doesn't exist, so response time doesn't reveal valid usernames.
const dummyHash = hashPassword(randomBytes(16).toString('hex'));

// chisle: in-memory user store; replace with a DB table (username unique, hash text)
const users = new Map();

const app = express();
if (prod) app.set('trust proxy', 1); // needed behind a proxy for req.ip and secure cookies
app.use(express.json()); // must precede the limiters: the per-user one reads req.body

// chisle: default MemoryStore; use connect-redis or similar before running more than one process
app.use(session({
  name: 'sid',
  secret: process.env.SESSION_SECRET,
  resave: false,
  saveUninitialized: false,
  cookie: { httpOnly: true, sameSite: 'lax', secure: prod, maxAge: 24 * 60 * 60 * 1000 },
}));

// --- rate limiting: only failed attempts (status >= 400) count ---
const failedOnly = {
  windowMs: 15 * 60 * 1000,
  skipSuccessfulRequests: true,
  standardHeaders: 'draft-7',
  legacyHeaders: false,
  message: { error: 'Too many failed attempts, try again later' },
};
const perIp = rateLimit({ ...failedOnly, limit: 20 });
// Per-username limit stops a distributed guess against one account.
const perUser = rateLimit({
  ...failedOnly,
  limit: 5,
  keyGenerator: (req) => `user:${String(req.body?.username)}`,
});

function credentials(req, res) {
  const { username, password } = req.body ?? {};
  if (typeof username === 'string' && username && typeof password === 'string' && password) {
    return { username, password };
  }
  res.status(400).json({ error: 'username and password required' });
}

app.post('/register', perIp, async (req, res) => {
  const creds = credentials(req, res);
  if (!creds) return;
  if (creds.password.length < 8) return res.status(400).json({ error: 'Password too short' });
  if (users.has(creds.username)) return res.status(409).json({ error: 'Username taken' });
  users.set(creds.username, { hash: await hashPassword(creds.password) });
  res.status(201).json({ ok: true });
});

app.post('/login', perIp, perUser, async (req, res) => {
  const creds = credentials(req, res);
  if (!creds) return;
  const user = users.get(creds.username);
  const ok = await verifyPassword(creds.password, user?.hash ?? (await dummyHash));
  if (!user || !ok) return res.status(401).json({ error: 'Invalid credentials' });

  // New session ID on login prevents session fixation.
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: 'Login failed' });
    req.session.username = creds.username;
    res.json({ ok: true });
  });
});

app.post('/logout', (req, res) => {
  req.session.destroy(() => res.clearCookie('sid').json({ ok: true }));
});

function requireAuth(req, res, next) {
  if (req.session.username) return next();
  res.status(401).json({ error: 'Not authenticated' });
}

app.get('/me', requireAuth, (req, res) => res.json({ username: req.session.username }));

app.listen(process.env.PORT ?? 3000);
```

Check:

```sh
SESSION_SECRET=dev node app.js &
curl -s -XPOST localhost:3000/register -H 'content-type: application/json' -d '{"username":"a","password":"correct-horse"}'
for i in 1 2 3 4 5 6; do curl -s -o /dev/null -w '%{http_code}\n' -XPOST localhost:3000/login -H 'content-type: application/json' -d '{"username":"a","password":"wrong"}'; done
# expect 401 x5, then 429
```

Security caveats:

- **Account lockout:** the per-username limiter lets anyone lock a known account out for 15 minutes with 5 bad guesses. Drop `perUser` if that matters more than resisting distributed guessing.
- **Username enumeration:** `/register` returns 409 for taken usernames, which reveals which accounts exist. The login path does not leak this.
- **CSRF:** `sameSite: 'lax'` is the only CSRF defence here. Add CSRF tokens if you add cookie-authenticated form posts from other origins or state-changing GET routes.
- **Single process only:** sessions and limiter counters live in memory, so they reset on restart and are not shared across instances.

